use NpmGateway\Contracts\CorporateToolsProviderInterface;use NpmGateway\Exceptions\Domain\InvalidCreditCardPurchaseException;use NpmGateway\Http\AuthenticatedRequestContext;use NpmGateway\Http\Request;use NpmGateway\Http\Response;use NpmGateway\Security\CsrfService;use NpmGateway\Services\CorporateAccessService;use NpmGateway\Services\CreditCardPurchaseService;use NpmGateway\Services\GatewayStorageService;use NpmGateway\Support\FlashSession;use NpmGateway\ValueObjects\CommunityActionContext;
