 public function __construct(private readonly CorporateAccessService $access,private readonly CreditCardPurchaseService $service,private readonly GatewayStorageService $storage,private readonly CorporateToolsProviderInterface $tools,private readonly CsrfService $csrf,private readonly FlashSession $flash,private readonly string $views){}
 public function index(Request $r,AuthenticatedRequestContext $request):Response{if(!$this->allowed($request))return $this->denied();$search=trim((string)($r->query['search']??''));$receipt=in_array(($r->query['receipt_status']??''),['attached','missing'],true)?(string)$r->query['receipt_status']:'';$selected=trim((string)($r->query['property']??''));$properties=$this->service->corporateProperties();$property=$selected===''?null:$this->service->corporateProperty($selected);$propertyId=$property?(int)$property['id']:null;$filtersActive=$search!==''||$receipt!==''||$selected!=='';$purchases=$property||$selected===''?$this->service->corporateList($search,$propertyId,$receipt):[];$summary=$property||$selected===''?$this->service->corporateSummary($search,$propertyId,$receipt):['total'=>0,'total_posted'=>'0.00','attached'=>0,'missing'=>0];$success=(string)$this->flash->pull('corporate_cc_success','');return $this->render('index',$request,compact('search','receipt','selected','properties','filtersActive','purchases','summary','success'));}
