 public function store(Request $r,AuthenticatedRequestContext $request):Response{if(!$this->allowed($request))return $this->denied();if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.',['Cache-Control'=>'private, no-store']);$propertyPublic=trim((string)($r->post['property_public_id']??''));$property=$this->service->corporateProperty($propertyPublic);if(!$property){$this->flash->put('corporate_cc_input',$r->post);$this->flash->put('corporate_cc_errors',['property_public_id'=>'Choose an active property.']);return Response::redirect('/corporate/credit-card-purchases/create');}try{if(!$this->allowed($request))return $this->denied();$c=$this->context($request,$property);$result=$this->service->post($c,$r->post,$r->files,'corporate');$this->flash->put('corporate_cc_success','Credit card purchase posted successfully.');return Response::redirect('/corporate/credit-card-purchases/'.$result['public_id']);}catch(InvalidCreditCardPurchaseException $e){$this->flash->put('corporate_cc_input',$e->input+['property_public_id'=>$propertyPublic]);$this->flash->put('corporate_cc_errors',$e->errors);return Response::redirect('/corporate/credit-card-purchases/create');}catch(\Throwable){return new Response(500,'The credit card purchase could not be saved safely.',['Cache-Control'=>'private, no-store']);}}
