 public function correct(Request $r,string $public,AuthenticatedRequestContext $request):Response{if(!$this->allowed($request))return $this->denied();if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.',['Cache-Control'=>'private, no-store']);$purchase=$this->service->corporateDetail($public);if(!$purchase)return $this->missing();try{if(!$this->allowed($request))return $this->denied();$this->service->correctCorporate($this->context($request,['id'=>$purchase['property_id'],'public_id'=>$purchase['property_public_id'],'slug'=>'corporate-credit-card-purchases','property_code'=>'','display_name'=>$purchase['property_name']]),$public,$r->post);$this->flash->put('corporate_cc_success','Credit card purchase corrected successfully.');return Response::redirect('/corporate/credit-card-purchases/'.$public);}catch(InvalidCreditCardPurchaseException $e){$this->flash->put('corporate_cc_correction_input',$e->input+['property_public_id'=>(string)($r->post['property_public_id']??'')]);$this->flash->put('corporate_cc_correction_errors',$e->errors);return Response::redirect('/corporate/credit-card-purchases/'.$public.'/edit');}catch(\OutOfBoundsException){return $this->missing();}catch(\Throwable){return new Response(500,'The correction could not be saved safely.',['Cache-Control'=>'private, no-store']);}}
