 private function document(string $purchase,string $receipt,AuthenticatedRequestContext $request,bool $download):Response{if(!$this->allowed($request))return $this->denied();$document=$this->service->corporateReceiptDocument($purchase,$receipt);if(!$document)return $this->missing();$object=$this->service->publishedReceipt(['storage_public_id'=>$document['storage_public_id']]);if(!$object||!$this->storage->available($object))return $this->missing();$mime=(string)$document['mime_type'];if(!in_array($mime,['application/pdf','image/jpeg','image/png'],true))return new Response(415,'This file type cannot be displayed in Gateway.',['Cache-Control'=>'private, no-store']);$name=preg_replace('/[^A-Za-z0-9._ -]/','_',basename((string)$document['display_filename']))?:'document';return new Response(200,'',['Content-Type'=>$mime,'Content-Disposition'=>($download?'attachment':'inline').'; filename="'.addcslashes($name,'"\\').'"','Content-Length'=>(string)(int)$document['byte_size'],'Cache-Control'=>'private, no-store','Pragma'=>'no-cache','X-Content-Type-Options'=>'nosniff','Cross-Origin-Resource-Policy'=>'same-origin','Content-Security-Policy'=>"default-src 'none'; frame-ancestors 'self'"],[],$this->storage->open($object));}
